UPDATE ${tableName}
SET demand        = #{demand},
    feedback_time = #{feedbackTime}
WHERE enterprise_code = #{enterpriseCode}
  AND delete_flag = 'f'
  AND feedback_code = #{feedbackCode}
  AND demand IS NULL
  AND feedback_time IS NULL

UPDATE ${tableName}
SET result      = #{result},
    handle_time = #{handleTime}
WHERE enterprise_code = #{enterpriseCode}
  AND delete_flag = 'f'
  AND feedback_code = #{feedbackCode}
  AND result IS NULL
  AND handle_time IS NULL

